const $=s=>document.querySelector(s);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storageKey='pull-gtm-workspace-v1';
let state={version:1,prospects:[],shortlist:[],drafts:{},audit:[],mode:'empty',identity:'Pull GTM',context:'company',persona:'business',website:'',offer:'',remember:false,setup:false,rules:{roles:'',industries:'',countries:'',min:'',max:'',signals:'',evidence:true,days:'90'},duplicates:0};
const defaults=structuredClone(state);
let cloud={configured:false,verified:false,user:null,revision:0,savedAt:null,dirty:false},pendingCloudLoad=null,localChange=0,workspaceOwner=null;
const accountGuard=new AccountGuard();
let accountChannel;try{accountChannel=new BroadcastChannel('pull-gtm-account');}catch{}
try{const saved=JSON.parse(localStorage.getItem(storageKey));if(saved?.version===1&&saved.remember&&Array.isArray(saved.prospects)&&Array.isArray(saved.shortlist)&&saved.rules&&saved.drafts&&Array.isArray(saved.audit)){workspaceOwner=saved.ownerAccountId||null;delete saved.ownerAccountId;state={...state,...validateWorkspace(saved),remember:true};}}catch{}
let view='home',tab='fit',query='',guideQuery='',accountMode='login',focusView='home';
let assistantState={configured:null,model:null,messages:[],busy:false,error:'',draft:'',lastMessage:'',shareContext:true,preparedPrompt:'',userId:null};
let aiPollTimer=null;
let agentState={configured:null,endpoint:null,tokens:[],busy:false,error:'',oneTime:null,userId:null};
let automationData={workflows:[],runs:[],loading:false};
