function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function syncWorkspaceIdentity(){const name=$('#workspace-name'),context=$('#workspace-context'),icon=$('#workspace-icon'),personal=state.context==='personal';if(name)name.textContent=personal?(cloud.verified?(profile?.display_name||cloud.user?.email?.split('@')[0]||'Personal profile'):'Personal profile'):state.identity;if(context)context.textContent=personal?'Personal workspace · no social linked':'Company workspace · no social linked';if(icon){icon.textContent=personal?(cloud.verified?initials(profile?.display_name||cloud.user?.email||'You').slice(0,2):'◉'):initials(state.identity).slice(0,2)||'C';if(personal&&cloud.verified&&cloud.user?.avatar_url)icon.innerHTML='<img src="'+escape(cloud.user.avatar_url)+'" alt="" referrerpolicy="no-referrer">';}}
