async function refreshAccount(){const epoch=accountGuard.epoch;try{const r=await cloudRequest('session');if(epoch!==accountGuard.epoch)return;cloud.configured=r.configured;cloud.providers=r.providers||{};if(!r.configured){accountGuard.suspend();cloud.verified=false;pendingCloudLoad=null;cloudLabel();return null;}setCloudUser(r.user);return r.user;}catch{if(epoch===accountGuard.epoch){accountGuard.suspend();cloud.verified=false;pendingCloudLoad=null;cloudLabel();}return null;}}
