  if(action==='cloud-apply-load'){
    if(!pendingCloudLoad)return;const loaded=pendingCloudLoad;button.disabled=true;await refreshAccount();button.disabled=false;
    if(!accountGuard.current(loaded.ticket)){toast('Your account changed. Open your cloud workspace again.');return;}pendingCloudLoad=null;
    state={...structuredClone(defaults),...loaded.payload,remember:false};workspaceOwner=loaded.ticket.id;cloud.revision=loaded.revision;cloud.savedAt=loaded.updated_at;
    save();cloud.dirty=false;$('#detail-dialog').close();query='';tab='fit';navigate('home');cloudLabel();toast('Loaded your saved workspace.');return;
  }
