async function loadAutomations(){
  if(!cloud.user||!cloud.verified){if(view==='automations')render();return;}
  const ticket=accountGuard.ticket();automationData.loading=true;
  try{const r=await cloudRequest('automations',undefined,ticket.id);if(!accountGuard.current(ticket))return;automationData={workflows:r.workflows||[],runs:r.runs||[],loading:false};if(view==='automations')render();}catch(error){automationData.loading=false;toast(error.message);}
}
async function runAutomation(action,id){
  if(!cloud.user||!cloud.verified){account();return;}
  const ticket=accountGuard.ticket(),version=localChange;
  try{
    const saved=await cloudRequest('workspace',{workspace:state,revision:cloud.revision},ticket.id);
    if(!accountGuard.current(ticket))return;cloud.revision=saved.revision;cloud.savedAt=saved.updated_at;cloud.dirty=localChange!==version;if(cloud.dirty)throw new Error('Your newer edits need saving. Run the workflow again when you finish editing.');
    const r=await cloudRequest('automations',{action,...(id?{id}:{}),revision:cloud.revision},ticket.id);
    if(!accountGuard.current(ticket))return;
    const loaded=await cloudRequest('workspace',undefined,ticket.id);if(!accountGuard.current(ticket)||!loaded.workspace)return;
    const data={...loaded.workspace,payload:validateWorkspace(loaded.workspace.payload),ticket};
    if(localChange!==version){pendingCloudLoad=data;modal('Your workflow has finished',`<p>You made newer local edits while it ran. Keep your work or load the workflow result. Download a backup before replacing your local copy.</p>`,`<button class="button secondary" data-action="backup">Download backup</button><button class="button secondary" data-action="close">Keep local work</button><button class="button primary" data-action="cloud-apply-load">Load workflow result</button>`);}
    else{const remember=state.remember;state={...structuredClone(defaults),...data.payload,remember};cloud.revision=data.revision;cloud.savedAt=data.updated_at;save();cloud.dirty=false;render();cloudLabel();toast('Workflow finished. Review the results and draft suggestions.');}
    await loadAutomations();
  }catch(error){toast(error.message);}
}
async function runImportAutomations(){
  if(!cloud.user||!cloud.verified)return;await loadAutomations();if(automationData.workflows.some(w=>w.enabled&&!w.archived_at&&w.trigger==='on_import'))await runAutomation('on_import');
}
